export fn ipv6_converter(a:?[*]const i64,n:usize,out:?[*]u8,cap:usize)i64{if(a==null or n<2)return -1;const v=a.?[0..n];const op=v[0];const len=v[1];if(!((op==0 and len==4)or(op==1 and len==16))or n!=@as(usize,@intCast(2+len)))return -1;for(v[2..])|x|{if(x<0 or x>255)return -1;}if(op==1){for(v[2..12])|x|{if(x!=0)return -1;}if(v[12]!=255 or v[13]!=255)return -1;}const needed:usize=if(op==0)16 else 4;if(out==null or cap<needed)return -2;const r=out.?[0..cap];if(op==0){@memset(r[0..10],0);r[10]=255;r[11]=255;for(0..4)|i|r[12+i]=@intCast(v[2+i]);}else{for(0..4)|i|r[i]=@intCast(v[14+i]);}return @intCast(needed);}
